INSERT INTO news (slug,title,excerpt,body,image,kind,author,status,published_at,legacy_id) VALUES ('ithrottaeldhugi-arsins-2026-oskad-eftir-tilnefningum','Íþróttaeldhugi ársins 2026, óskað eftir tilnefningum','Íþróttaeldhugi ársins verður tilnefndur samhliða kjöri á Íþróttamanni ársins 2026. Lottó og Íþrótta- og Ólympíusamband Íslands standa fyrir þessari tilnefningu.','<p>Íþróttaeldhugi ársins verður tilnefndur samhliða kjöri á Íþróttamanni ársins 2026. Lottó og Íþrótta- og Ólympíusamband Íslands standa fyrir þessari tilnefningu.</p><p>Almenningi gefst kostur á að senda inn ábendingar um öfluga sjálfboðaliða til 5. desember, sjá <a href="https://www.isi.is">www.isi.is</a>. Leitað er eftir framúrskarandi sjálfboðaliðum sem hafa í gegnum árin nýtt eigin hæfileika, frítíma og sérþekkingu til að efla íþróttastarf.</p>','/media/seed/ithrottaeldhugi.jpg','frett','','published','2026-11-27 10:00:00',8661);
INSERT INTO news (slug,title,excerpt,body,image,kind,author,status,published_at,legacy_id) VALUES ('olympiufari-faer-starfslaun-afreksithrottafolks','Ólympíufari fær starfslaun afreksíþróttafólks','Hákon Þór Svavarsson úr Skotíþróttafélagi Suðurlands er meðal þeirra sem fá starfslaun afreksíþróttafólks frá 1. nóvember sl. til ársloka 2027.','<p>Hákon Þór Svavarsson úr Skotíþróttafélagi Suðurlands er meðal þeirra sem fá starfslaun afreksíþróttafólks frá 1. nóvember sl. til ársloka 2027.</p>','/media/seed/hakon.jpg','frett','','published','2026-11-26 10:00:00',8660);
INSERT INTO news (slug,title,excerpt,body,image,kind,author,status,published_at,legacy_id) VALUES ('dagur-sjalfbodalidans-framundan-oskad-er-eftir-tilnefningum','Dagur sjálfboðaliðans framundan, óskað er eftir tilnefningum','Árið 1985 ákváðu Sameinuðu þjóðirnar að 5. desember yrði helgaður sjálfboðaliðum. Síðan þá hefur dagurinn verið haldinn hátíðlegur víða um heim ár hvert.','<p>Árið 1985 ákváðu Sameinuðu þjóðirnar að 5. desember yrði helgaður sjálfboðaliðum. Síðan þá hefur dagurinn verið haldinn hátíðlegur víða um heim ár hvert.</p>','/media/seed/sjalfbodalidar.png','frett','','published','2026-11-24 10:00:00',8659);
INSERT INTO news (slug,title,excerpt,body,image,kind,author,status,published_at,legacy_id) VALUES ('avarp-formanns-hsk-a-heradsthingi-2026','Ávarp formanns HSK á héraðsþingi 2026','Að taka þátt í skipulögðu íþróttastarfi hefur, í öllum aldurshópum, ekki bara áhrif á líkamshreysti heldur einnig félagslega og andlega líðan.','<p>Að taka þátt í skipulögðu íþróttastarfi hefur, í öllum aldurshópum, ekki bara áhrif á líkamshreysti heldur einnig félagslega og andlega líðan.</p>','','grein','Guðríður Aadnegard','published','2026-03-26 12:00:00',NULL);
